            "consent_modal_section_1_text": "Я даю свое согласие компании Aladdin на обработку персональных данных в целях использования приложения ALADDIN Family (далее - «Приложение»), создания семейного аккаунта, настройки функций безопасности и защиты семьи.",
            "consent_modal_section_2_title": "2. Персональные данные",
            "consent_modal_section_2_text": "Обработке подлежат следующие персональные данные: роль в семье (родитель/ребенок/бабушка-дедушка), возрастная группа, личная буква для идентификации.",
            "consent_modal_section_3_title": "3. Способы обработки",
            "consent_modal_section_3_text": "Персональные данные обрабатываются с использованием автоматизированных средств (приложение, сервер, база данных). Данные хранятся локально на устройстве пользователя и передаются на сервер компании для обеспечения работы семейного доступа.",
            "consent_modal_section_4_title": "4. Сроки обработки",
            "consent_modal_section_4_text": "Персональные данные обрабатываются в течение всего срока использования Приложения и до момента отзыва согласия пользователем или до момента прекращения действия Приложения.",
            "consent_modal_section_5_title": "5. Права пользователя",
            "consent_modal_section_5_text": "Я подтверждаю, что ознакомлен(а) с правами пользователя, предусмотренными Федеральным законом «О персональных данных» № 152-ФЗ, в том числе с правом на получение информации об обработке моих персональных данных, правом на доступ к моим персональным данным, правом на требование уточнения, блокирования или уничтожения моих персональных данных.",
            "consent_modal_section_6_title": "6. Согласие распространяется на:",
            "consent_modal_section_6_text": "- Создание и управление семейным аккаунтом\n- Генерацию и использование QR-кодов для доступа\n- Сохранение настроек безопасности семьи\n- Использование данных для работы функций родительского контроля\n- Обработку данных о роли и возрасте для персонализации интерфейса",
            "consent_modal_section_7_title": "7. Гарантии компании",
            "consent_modal_section_7_text": "- Не собираем номер телефона, email, имя или другие персональные данные\n- Не передаем данные третьим лицам\n- Используем данные исключительно для работы функций Приложения\n- Обеспечиваем безопасное хранение данных\n- Соблюдаем требования законодательства о защите персональных данных",
            "consent_modal_section_8_title": "8. Отзыв согласия",
            "consent_modal_section_8_text": "Я понимаю, что вправе отозвать настоящее согласие на обработку персональных данных в любой момент, направив соответствующее уведомление в компанию Aladdin. При этом я понимаю, что отзыв согласия может повлечь невозможность использования Приложения.",
            "consent_modal_agree": "Согласен и продолжаю",
