            "consent_modal_section_5_text": "I confirm that I am familiar with the user rights provided for by Federal Law \"On Personal Data\" No. 152-FZ, including the right to receive information about the processing of my personal data, the right to access my personal data, the right to demand clarification, blocking or destruction of my personal data.",
            "consent_modal_section_6_title": "6. Consent applies to:",
            "consent_modal_section_6_text": "- Creating and managing a family account\n- Generating and using QR codes for access\n- Saving family security settings\n- Using data for parental control features\n- Processing data about role and age for interface personalization",
            "consent_modal_section_7_title": "7. Company guarantees",
            "consent_modal_section_7_text": "- We do not collect phone number, email, name or other personal data\n- We do not transfer data to third parties\n- We use data exclusively for Application functionality\n- We ensure secure data storage\n- We comply with personal data protection legislation requirements",
            "consent_modal_section_8_title": "8. Consent withdrawal",
            "consent_modal_section_8_text": "I understand that I have the right to withdraw this consent to process personal data at any time by sending a corresponding notification to Aladdin company. At the same time, I understand that withdrawal of consent may result in the inability to use the Application.",
            "consent_modal_agree": "Agree and continue",
