    // MARK: - Get Localized String
    // MARK: - Recursion Protection
    private static let recursionKey = "LocalizationManager.isLocalizing"

    // ✅ BUILD 113: Добавляем Lock для защиты гигантского словаря (9000+ строк)
    // Доступ к Dictionary в Swift не потокобезопасен, что вызывает Dictionary.resize краш.
    private let lock = NSLock()

    /**
     * Получить локализованную строку из словаря переводов
     * ✅ РАБОТАЕТ БЕЗ ФАЙЛОВ ЛОКАЛИЗАЦИИ!
     */
    func localized(_ key: String) -> String {
        // 🛡️ BUILD 112: Защита от рекурсии при поиске переводов
        let threadDict = Thread.current.threadDictionary
        if threadDict[Self.recursionKey] != nil {
            return key // Возвращаем сам ключ при обнаружении рекурсии
        }
        threadDict[Self.recursionKey] = true
        defer { threadDict.removeObject(forKey: Self.recursionKey) }

        // 🛡️ BUILD 113: Гарантированная потокобезопасность для гигантского словаря
        lock.lock()
        defer { lock.unlock() }

        // ✅ СНАЧАЛА проверяем словарь переводов для текущего языка
        if let translation = translations[currentLanguage]?[key] {
            return translation
        }
        
        // ✅ ЕСЛИ текущий язык - русский, но перевод не найден, пробуем принудительно русский
        if currentLanguage == .russian, let russianTranslation = translations[.russian]?[key] {
            return russianTranslation
        }
        
        // Если перевода нет, пробуем NSLocalizedString (для будущих файлов локализации)
        let nsLocalized = NSLocalizedString(key, comment: "")
        if nsLocalized != key {
            return nsLocalized
        }
        
        // ✅ ФИНАЛЬНЫЙ FALLBACK: Проверяем русский словарь если язык не русский
        if currentLanguage != .russian, let russianFallback = translations[.russian]?[key] {
            return russianFallback
        }
        
        // Если ничего не найдено, возвращаем ключ
        return key
    }
    /**
     * Получить локализованную строку с параметрами
     */
    func localized(_ key: String, _ arguments: CVarArg...) -> String {
        let template = localized(key)
        return String(format: template, arguments: arguments)
    }
}

#if DEBUG
enum LocalizationDiagnostics {
    private static let childRewardSettingKeys = [
        "child_rewards_settings_title",
        "child_rewards_settings_subtitle",
        "child_rewards_settings_goal_title",
        "child_rewards_settings_goal_name_label",
        "child_rewards_settings_goal_name_placeholder",
        "child_rewards_settings_goal_cost_label",
        "child_rewards_settings_goal_cost_placeholder",
        "child_rewards_settings_edit_button",
        "child_rewards_settings_save_button",
        "child_rewards_settings_info_title",
        "child_rewards_settings_info_text"
    ]
    
    static func runInitialChecks(with manager: LocalizationManager) {
        verifyChildRewardsSettingsKeys(using: manager)
    }
    
    private static func verifyChildRewardsSettingsKeys(using manager: LocalizationManager) {
        let ruDict = manager.translations[.russian] ?? [:]
        let enDict = manager.translations[.english] ?? [:]
        
        let missingRU = childRewardSettingKeys.filter { ruDict[$0] == nil }
        let missingEN = childRewardSettingKeys.filter { enDict[$0] == nil }
        
        if missingRU.isEmpty && missingEN.isEmpty {
            print("✅ LocalizationDiagnostics: child_rewards_settings ключи найдены в RU/EN")
        } else {
            if !missingRU.isEmpty {
                print("⚠️ LocalizationDiagnostics: отсутствуют RU ключи: \(missingRU.joined(separator: ", "))")
            }
            if !missingEN.isEmpty {
                print("⚠️ LocalizationDiagnostics: отсутствуют EN ключи: \(missingEN.joined(separator: ", "))")
            }
        }
    }
}
#endif
// MARK: - String Extension

extension String {
    /**
     * Удобный helper для локализации
     * Использование: "main.title".localized
     */
    var localized: String {
        NSLocalizedString(self, comment: "")
    }
    
    /**
     * Локализация с параметрами
     * Использование: "family.subtitle".localized(4)
     */
    func localized(_ arguments: CVarArg...) -> String {
        String(format: NSLocalizedString(self, comment: ""), arguments: arguments)
    }
}

// MARK: - LocalizedStringKey Extension

extension LocalizedStringKey {
    /**
     * Создать из строки
     */
    static func key(_ string: String) -> LocalizedStringKey {
        LocalizedStringKey(string)
    }
}
